  view:'fleet'|'requirements'|'settings'|'history'='fleet';
  history:HistoryEntry[]=[];requests:AuditRequest[]=[];historyUsage:HistoryUsage={audits:0,files:0,bytes:0};historyReport:Report|null=null;historyComparison:Comparison|null=null;historyId='';reportFilter:string|null=null;reportSearch='';
  session:Session|null=null;mode:'LOCAL'|'OIDC'|null=null;clients:Client[]=[];identity:Identity|null=null;comparison:Comparison|null=null;language='en';loading=true;busy=false;error='';
  pendingClientIdentity:(Identity&{schemaVersion:string;role:string;algorithm:string;createdAtUnixMs?:number})|null=null;pendingClientName='';pairingError='';pairedClient:Client|null=null;
  readonly knownRequirementIds=['REQ-001','REQ-002','REQ-003','REQ-004','REQ-005','REQ-006','REQ-007','REQ-008','REQ-009'];
  requestId='';selectedId='';selectedName='';status:RequestStatus|null=null;report:Report|null=null;retryCreate=false;auditModalOpen=false;
  shaDialog:{kind:'client'|'manifest';clientId?:string;name:string;hasOverride:boolean}|null=null;shaValue='';shaError='';
  private shaReturnFocus:HTMLElement|null=null;private shaPreviousOverflow='';
  private auditReturnFocus:HTMLElement|null=null;
