  t(key:string):string{return this.messages['server.'+key]||key;}
  get displayedReport():Report|null{return this.auditModalOpen?this.historyReport:null;}
  get displayedComparison():Comparison|null{return this.auditModalOpen?this.historyComparison:null;}
  get manifestWarning():boolean{return !!this.historyReport?.installation && (this.historyReport.installation.status!=='VERIFIED'||this.historyComparison?.manifest?.state!=='MATCH');}
  get reportPdfUrl():string{return '/api/history/'+encodeURIComponent(this.historyId)+'/pdf';}
  get auditRows():AuditRequest[]{const rows=this.requests.filter(request=>!this.history.some(saved=>saved.id===request.requestId));for(const saved of this.history)rows.push({requestId:saved.id,clientId:saved.clientId,clientName:saved.clientName,issuedAtUnixMs:saved.completedAtUnixMs,status:{requestId:saved.id,state:'COMPLETED',resultAvailable:true}});return rows.sort((a,b)=>b.issuedAtUnixMs-a.issuedAtUnixMs);}
